export function recommendBenchmarkTrack(score){return score<=1?'explorer':score===2?'strategist':'architect'}
export function compareFractions(a,b,c,d){return a*d-c*b}
export function benchmarkZone(n,d){const x=2*n;return x<d?'below 1/2':x===d?'equal to 1/2':'above 1/2'}
export function fractionOf(n,d,whole){return whole*n/d}
